"""Phase 7 : réponses françaises fondées sur les mesures et contrôlées en longueur."""
import json
import re
import pandas as pd
from commun import ROOT, sauvegarde

def main():
    o=json.loads((ROOT/'reports/orange_resultats.json').read_text(encoding='utf-8'))
    f=json.loads((ROOT/'reports/flaml_resultats.json').read_text(encoding='utf-8'))
    k=json.loads((ROOT/'reports/knime_simulation_resultats.json').read_text(encoding='utf-8'))
    df=pd.read_csv(ROOT/'data/transactions.csv')
    brut=o['avant']['kNN']; norm=o['apres']['kNN']; gb=o['apres']['Gradient Boosting']; seuil=o['seuil_0_3']
    tn,fp=gb['matrice'][0]; fn,tp=gb['matrice'][1]
    tn3,fp3=seuil['matrice'][0]; fn3,tp3=seuil['matrice'][1]
    reponses={
    'Q1 Exactitude et F1': f"""Nos mesures Orange (API Python) donnent au kNN une exactitude de {brut['CA']:.3f}, mais un F1 fraude de {brut['F1']:.6f}. Cette différence vient du déséquilibre : la classe 0 représente {1-df.fraude.mean():.4f} des transactions. Une prédiction toujours égale à zéro atteint donc cette exactitude, avec un rappel et un F1 fraude nuls. Le kNN brut ne retrouve que {brut['Recall']:.6f} des fraudes du test. L’exactitude masque ainsi une grande partie des erreurs qui intéressent la banque. Le kNN compare des distances ; montant, dont la médiane mesurée vaut {df.montant.median():.2f}, possède une échelle beaucoup plus grande que nuit, binaire, et peut dominer anciennete ou freq_24h. Les voisinages reflètent alors surtout le montant. La standardisation apprise uniquement sur l’apprentissage rééquilibre les attributs continus. Notre F1 passe à {norm['F1']:.6f} et le rappel à {norm['Recall']:.6f}. Cette amélioration observée justifie le prétraitement, sans garantir sa pertinence pour toutes les distributions futures. Les arbres reposent davantage sur des seuils que sur des distances et sont donc moins sensibles aux unités.""",
    'Q2 Reproductibilité': f"""Fixer les graines permet d’attribuer une différence de score à une modification identifiable. Notre forêt Orange (API Python) obtient un F1 de {o['avant']['Random Forest']['F1']:.6f} avec dix arbres puis {o['apres']['Random Forest']['F1']:.6f} avec cent arbres, sur exactement le même test. Le code installé montre que Replicable training transmet random_state=0. Sans graine, les tirages de lignes et d’attributs changeraient : on pourrait retenir un modèle simplement favorisé par le hasard. Nous n’avons pas mesuré ici une forêt non déterministe ; les variations citées dans l’énoncé restent des valeurs attendues non reproduites. En MLOps, cette variabilité complique audit, débogage, comparaison et contrôles de non régression en intégration continue. Dans KNIME, il faut cocher Use static random seed ; dans scikit-learn, renseigner random_state ; dans FLAML, seed. Nous utilisons aussi la graine 42 pour les partages et la validation croisée Orange. Une graine ne suffit toutefois pas à reproduire des versions différentes : dépendances, données, paramètres, parallélisme et budget temps doivent également être consignés.""",
    'Q3 Coût des erreurs et seuil': f"""La matrice mesurée avec Orange (API Python) contient {fn} fraudes manquées et {fp} fausses alertes, pour {tp} fraudes détectées. Une fraude manquée expose généralement la banque à une perte financière ; une fausse alerte provoque de la friction client et mobilise des analystes. Nous ne disposons pas de coûts métier chiffrés : affirmer un coût total serait inventer une information. Le volume d’alertes peut aussi saturer le traitement et rendre certaines fraudes moins visibles. Abaisser le seuil de décision favorise le rappel. Nous avons réellement recalculé les prédictions GB avec un seuil de 0,3 au lieu de 0,5 : la matrice devient [[{tn3},{fp3}],[{fn3},{tp3}]], le rappel atteint {seuil['Recall']:.6f} et le F1 {seuil['F1']:.6f}. Nous récupérons donc {fn-fn3} fraudes supplémentaires, mais ajoutons {fp3-fp} fausses alertes. Ce seuil illustre le compromis et n’est pas une recommandation de production. Il faut choisir le seuil sur validation selon les coûts et la capacité des équipes, puis vérifier sur un test indépendant. Les probabilités, les pondérations de classes et ROC Analysis avec coûts FP/FN aident cette décision.""",
    'Q4 Déclarer la cible': f"""Dans le workflow KNIME décrit par l’énoncé, fraude est lue comme un entier par CSV Reader. Les Learners de classification demandent une cible nominale : Number to String convertit uniquement cette colonne en catégories textuelles « 0 » et « 1 ». Une cible numérique peut être absente de Target column ou empêcher la configuration du nœud. Convertir tous les attributs serait une erreur différente, car montant et les compteurs perdraient leur représentation quantitative. Dans Orange, le geste équivalent consiste à choisir Role=target et Type=categorical dans File, puis Apply. Notre domaine Orange (API Python) comporte bien quatre attributs, dont nuit catégorielle, et une cible fraude discrète ; le partage testé contient {int(df.fraude.sum())} fraudes au total. Si l’on conserve une cible continue, les widgets compatibles sélectionnent la régression et Test and Score propose notamment MSE/RMSE ; certains Learners exclusivement classificatoires peuvent refuser les données. Le contrôle du type et du rôle doit donc précéder toute lecture de F1. Cette vérification a été répétée lors de la recharge du workflow généré.""",
    'Q5 Deux environnements visuels': f"""Orange recalcule les widgets lorsque les données ou les paramètres changent. Dans notre reproduction Orange (API Python), Test and Score entraîne les cinq Learners sur 3750 lignes et évalue leurs prédictions sur 1250 autres. Pour un débutant, cette interaction facilite l’exploration : le passage du F1 kNN de {brut['F1']:.3f} à {norm['F1']:.3f} devient immédiatement interprétable. Elle peut toutefois masquer les entraînements déclenchés et rendre le protocole difficile à suivre sans annotations. Selon le fonctionnement décrit dans l’énoncé, KNIME demande une exécution explicite ; les feux signalent configuration, préparation et exécution. Learner et Predictor sont séparés, ce qui rend visibles le modèle appris et les données auxquelles il s’applique. Le workflow est plus long à construire, mais cette explicitation aide à organiser les contrôles et la maintenance en équipe. Les possibilités de partage via Hub et de déploiement présenté dans le bonus favorisent un processus plus structuré, sans assurer seules sa gouvernance. Nous n’avons pas manipulé l’interface KNIME : cette comparaison d’usage doit être complétée par les observations personnelles de l’étudiant.""",
    'Q6 Outils visuels et mise en production': f"""Notre Gradient Boosting atteint {gb['F1']:.6f} de F1 avec Orange (API Python). La référence FLAML réellement exécutée en Python, de provenance simulation scikit-learn, retient {f['meilleur_modele']} avec un F1 externe de {f['resultats']['F1']:.6f}. Les tests diffèrent : ces valeurs n’établissent pas une supériorité universelle. La valeur TP2 de 0,8669 reste une valeur attendue de l’énoncé, non reproduite. Les outils visuels gardent un intérêt pour apprendre, expliquer et prototyper avec des utilisateurs peu familiers du code. Orange sert l’exploration rapide ; KNIME explicite les étapes d’un processus ; FLAML et le code facilitent l’automatisation, les tests et l’intégration MLOps. Pour produire fraude-gb.pkcls, nous avons sauvegardé un vrai modèle et vérifié sa recharge. Cela reste insuffisant pour la production du TP05 : il faut figer les dépendances, notamment Orange, conserver le prétraitement dans le pipeline, définir un contrat de données, exposer une API de serving, ajouter tests et conteneurisation, enregistrer les versions dans un registre tel que MLflow, puis surveiller erreurs et dérive. Le seuil, sa justification métier et sa procédure de révision doivent aussi être gérés.""",
    'B2 Validation croisée et test fixe': f"""Avec Orange (API Python), notre F1 GB est {gb['F1']:.6f} sur le test fixe et {o['cv']['apres']['Gradient Boosting']['F1']:.6f} en validation croisée stratifiée à cinq plis. La régression logistique passe de {o['avant']['Logistic Regression']['F1']:.6f} à {o['cv']['apres']['Logistic Regression']['F1']:.6f}. Le test fixe entraîne chaque modèle sur 3750 lignes et le juge sur les mêmes 1250 lignes réservées. La validation croisée réentraîne cinq modèles par algorithme : chacun apprend sur 4000 lignes et prédit les 1000 lignes de son pli. Chaque transaction est ainsi évaluée une fois hors apprentissage. Le protocole et la taille d’apprentissage changent ; la difficulté des observations aussi. Le code de scoring Orange calcule ici le F1 sur les prédictions hors pli regroupées. La moyenne des cinq F1 GB vaut {o['cv']['apres']['Gradient Boosting']['F1_moyenne_plis']:.6f}, légèrement différente du score agrégé ; les deux sont archivés. La CV décrit la variabilité entre plis, mais les ensembles d’apprentissage se recouvrent : elle ne crée pas cinq expériences indépendantes. On ne doit donc pas interpréter l’écart au test fixe comme une dégradation certaine du modèle.""",
    'B3 Prédictions et courbes ROC': f"""Sur notre test fixe avant amélioration, le kNN a la plus faible AUC, {brut['AUC']:.6f}, contre {gb['AUC']:.6f} pour Gradient Boosting, selon Orange (API Python). Ses distances dominées par les grandes échelles produisent un classement moins pertinent des transactions. Après standardisation, son AUC atteint {norm['AUC']:.6f} ; Tree devient alors le plus faible globalement, avec {o['apres']['Tree']['AUC']:.6f}. Préciser avant ou après est indispensable pour répondre honnêtement à la question. Dans la CV après amélioration, Tree possède aussi la plus faible AUC, {o['cv']['apres']['Tree']['AUC']:.6f}. Une courbe peut croiser une autre : « la plus basse » désigne ici la plus faible aire globale, pas une domination à chaque seuil. La ROC compare rappel et taux de faux positifs quand le seuil varie ; elle ne donne pas directement le coût des alertes dans une population déséquilibrée. Predictions permet d’inspecter les probabilités individuelles de classe 1 et les erreurs. Nos figures représentent les calculs Python, sans remplacer la capture Orange. Le workflow relie effectivement le modèle GB et les 1250 transactions réservées à Predictions.""",
    }
    comptes={titre:len(texte.split()) for titre,texte in reponses.items()}
    assert all(120 <= n <= 200 for n in comptes.values()),comptes
    texte='# Questions et bonus analysés\n\n'
    texte+='Sources : nos JSON/CSV de résultats et le PDF local. Les nombres de protocole sont contrôlés par les scripts. '
    texte+='Orange (API Python) désigne les mesures Orange ; simulation scikit-learn désigne les calculs Python de simulation KNIME et la référence FLAML exécutée.\n\n'
    for titre,reponse in reponses.items():
        texte+=f'## {titre}\n\n{reponse}\n\n'
    (ROOT/'reports/questions_reponses.md').write_text(texte,encoding='utf-8')
    sauvegarde('questions_validation.json',{'comptage':'Mots séparés par espaces, titres exclus',
                                           'mots_par_reponse':comptes,'minimum':120,'maximum':200,
                                           'mediane_montant':float(df.montant.median()),
                                           'provenance_statistique_donnees':'simulation scikit-learn : lecture pandas du CSV synthétique Annexe A'})
    print(comptes)

if __name__ == '__main__':
    main()
